package org.pyapp.demo

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.provider.Settings
import android.view.Gravity
import android.widget.*

class MainActivity : Activity() {

    private val requestCode = 501

        override fun onCreate(savedInstanceState: Bundle?) {
                super.onCreate(savedInstanceState)

                        val layout = LinearLayout(this).apply {
                                    orientation = LinearLayout.VERTICAL
                                                gravity = Gravity.CENTER
                                                            setPadding(25, 30, 25, 30)
                                                                    }

                                                                            layout.addView(TextView(this).apply {
                                                                                        text = "🎱 Floating Line Trainer"
                                                                                                    textSize = 25f
                                                                                                            })

                                                                                                                    layout.addView(Button(this).apply {
                                                                                                                                text = "Grant Overlay Permission"

                                                                                                                                            setOnClickListener {
                                                                                                                                                            if (!Settings.canDrawOverlays(this@MainActivity)) {
                                                                                                                                                                                val intent = Intent(
                                                                                                                                                                                                        Settings.ACTION_MANAGE_OVERLAY_PERMISSION,
                                                                                                                                                                                                                                Uri.parse("package:$packageName")
                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                        startActivityForResult(intent, requestCode)
                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                            startOverlay()
                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                })

                                                                                                                                                                                                                                                                                                                                                        layout.addView(Button(this).apply {
                                                                                                                                                                                                                                                                                                                                                                    text = "Start Floating Menu"
                                                                                                                                                                                                                                                                                                                                                                                setOnClickListener {
                                                                                                                                                                                                                                                                                                                                                                                                if (Settings.canDrawOverlays(this@MainActivity)) {
                                                                                                                                                                                                                                                                                                                                                                                                                    startOverlay()
                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        Toast.makeText(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                this@MainActivity,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Please grant overlay permission",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Toast.LENGTH_SHORT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ).show()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                layout.addView(Button(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            text = "Stop Floating Menu"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setOnClickListener {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        stopService(Intent(this@MainActivity, OverlayService::class.java))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setContentView(layout)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            private fun startOverlay() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val intent = Intent(this, OverlayService::class.java)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        startForegroundService(intent)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            startService(intent)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            @Deprecated("Deprecated API retained for compatibility")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                override fun onActivityResult(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        requestCode: Int,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                resultCode: Int,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        data: Intent?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    super.onActivityResult(requestCode, resultCode, data)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (requestCode == this.requestCode &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Settings.canDrawOverlays(this)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    startOverlay()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }